191:     SELECT quantity, unit_price, line_total, discount_allocated, billing_owner
192:       INTO dong
193:       FROM public.payment_bill_line
194:      WHERE id = NEW.payment_bill_line_id AND clinic_id = NEW.clinic_id;
195:     IF dong.billing_owner IS DISTINCT FROM 'CLINIC' OR dong.unit_price IS NULL THEN
