199:     SELECT coalesce(sum(l.quantity), 0), coalesce(sum(l.amount), 0)
200:       INTO da_hoan, da_hoan_tien
201:       FROM public.payment_refund_line l
202:       JOIN public.payment_refund r
203:         ON r.refund_id = l.refund_id AND r.clinic_id = l.clinic_id
204:      WHERE l.payment_bill_line_id = NEW.payment_bill_line_id
205:        AND l.clinic_id = NEW.clinic_id
206:        AND r.status IN ('PENDING', 'COMPLETED');
207:     IF da_hoan + NEW.quantity > dong.quantity THEN
208:         RAISE EXCEPTION 'Hoàn vượt số đã thu của dòng (% + % > %)',
209:             da_hoan, NEW.quantity, dong.quantity
210:             USING ERRCODE = 'check_violation';
211:     END IF;
212:     IF dong.discount_allocated = 0 THEN
213:         IF NEW.amount <> round(NEW.quantity * dong.unit_price) THEN
214:             RAISE EXCEPTION 'Số tiền hoàn phải = số lượng × đơn giá ảnh chụp'
215:                 USING ERRCODE = 'check_violation';
216:         END IF;
217:     ELSIF da_hoan_tien + NEW.amount > dong.line_total THEN
218:         RAISE EXCEPTION 'Hoàn vượt số đã thu của dòng sau giảm giá (% + % > %)',
219:             da_hoan_tien, NEW.amount, dong.line_total
220:             USING ERRCODE = 'check_violation';
221:     END IF;
222:     RETURN NEW;
223: END $$;
